  { id: 'bio10-m2-s031', questionId: 'bio10-m2-q031', recognition: 'Không quan sát thấy chỉ cho biết giới hạn phương pháp, không tự động chứng minh cấu trúc vắng mặt.', detailedSteps: [{ order: 1, title: 'Xét giới hạn thiết bị', explanation: 'Mitochondria nhỏ, độ tương phản thấp và khó nhận diện với tiêu bản/kính hiện tại.' }, { order: 2, title: 'Giới hạn kết luận', explanation: 'Cần nhuộm hoặc phương pháp phân giải cao hơn; chưa thể kết luận không có. Chọn A.' }], finalAnswer: 'A', commonMistakes: ['Đồng nhất không thấy với không tồn tại.'], reviewSuggestions: ['Ôn BIO10-M2-O08.'] }
  ,{ id: 'bio10-m2-s032', questionId: 'bio10-m2-q032', recognition: 'Cơ thể đơn bào chỉ có một tế bào nên tế bào đó phải đảm nhiệm mọi chức năng sống.', detailedSteps: [{ order: 1, title: 'Xác định số tế bào', explanation: '“Đơn bào” nghĩa là cơ thể gồm một tế bào.' }, { order: 2, title: 'Chọn cấp thực hiện', explanation: 'Chuyển hóa, cảm ứng và sinh sản diễn ra ở chính tế bào đó. Chọn B.' }], finalAnswer: 'B', commonMistakes: ['Tự thêm mô và cơ quan vào cơ thể đơn bào.'], reviewSuggestions: ['Ôn BIO10-M2-O01.'] }
  ,{ id: 'bio10-m2-s033', questionId: 'bio10-m2-q033', recognition: '“Đơn vị chức năng” hỏi nơi các hoạt động sống cơ bản được thực hiện.', detailedSteps: [{ order: 1, title: 'Xét tế bào', explanation: 'Tế bào có hệ enzyme, màng và vật chất di truyền để duy trì hoạt động.' }, { order: 2, title: 'Xét cơ thể đa bào', explanation: 'Chức năng cơ thể là kết quả phối hợp hoạt động của tế bào. Chọn C.' }], finalAnswer: 'C', commonMistakes: ['Cho rằng tế bào chỉ là viên gạch thụ động.'], reviewSuggestions: ['Ôn BIO10-M2-O01.'] }
  ,{ id: 'bio10-m2-s034', questionId: 'bio10-m2-q034', recognition: 'Các cấu trúc và quá trình chung ở nhiều nhóm sinh vật là bằng chứng tính thống nhất cấp tế bào.', detailedSteps: [{ order: 1, title: 'Liệt kê điểm chung', explanation: 'Màng, ribosome, DNA và chuyển hóa xuất hiện rộng khắp.' }, { order: 2, title: 'Suy ra nguyên lí', explanation: 'Các điểm chung cho thấy nền tảng tổ chức sống thống nhất. Chọn D.' }], finalAnswer: 'D', commonMistakes: ['Suy tính thống nhất thành mọi tế bào giống hệt nhau.'], reviewSuggestions: ['Ôn BIO10-M2-O01.'] }
  ,{ id: 'bio10-m2-s035', questionId: 'bio10-m2-q035', recognition: 'Lớn lên của cơ thể đa bào không thể dựa vào tế bào phình vô hạn vì giới hạn trao đổi chất.', detailedSteps: [{ order: 1, title: 'Xét số lượng', explanation: 'Phân bào làm tăng số tế bào.' }, { order: 2, title: 'Xét tổ chức', explanation: 'Tăng trưởng còn gồm tăng kích thước có giới hạn và biệt hóa. Chọn B.' }], finalAnswer: 'B', commonMistakes: ['Chỉ xét kích thước từng tế bào.'], reviewSuggestions: ['Ôn BIO10-M2-M01.'] }
  ,{ id: 'bio10-m2-s036', questionId: 'bio10-m2-q036', recognition: 'Bằng chứng cho “đơn vị cấu trúc” phải trực tiếp cho thấy mô/cơ quan được hợp thành từ tế bào.', detailedSteps: [{ order: 1, title: 'Xác định mệnh đề cần chứng minh', explanation: 'Đơn vị cấu trúc nói về thành phần tạo cơ thể.' }, { order: 2, title: 'Chọn quan sát trực tiếp', explanation: 'Ảnh mô gồm tế bào sắp xếp có tổ chức hỗ trợ mạnh nhất. Chọn C.' }], finalAnswer: 'C', commonMistakes: ['Chọn hiện tượng sống không cho biết cấu tạo.'], reviewSuggestions: ['Ôn BIO10-M2-O01.'] }
  ,{ id: 'bio10-m2-s037', questionId: 'bio10-m2-q037', recognition: 'Có DNA và protein chưa đủ; tế bào cần ranh giới, bộ máy tổng hợp và chuyển hóa tự duy trì.', detailedSteps: [{ order: 1, title: 'Kiểm tra cấu trúc tối thiểu', explanation: 'Thiếu màng, tế bào chất và ribosome.' }, { order: 2, title: 'Kiểm tra chức năng', explanation: 'Không tự duy trì chuyển hóa/sinh sản nên chưa là tế bào. Chọn D.' }], finalAnswer: 'D', commonMistakes: ['Dùng sự có mặt DNA làm tiêu chí duy nhất.'], reviewSuggestions: ['Ôn BIO10-M2-O01.'] }
